#!/usr/bin/env bash
#
# Template Count Ablation (Table 4d Rerun)
#
# Trains CLIP InfoNCE and SigLIP on HAR with 1, 3, 5, and 10 Level-1-only
# templates per class, using separate pair registries generated by
# scripts/paper_experiments/generate_template_count_registries.py.
#
# All checkpoints and results are written to *_rerun directories so that
# previous runs are never overwritten.
#
# Prerequisites:
#   1. Fill in har_extended_templates.py (replace TODO placeholders)
#   2. Run: python scripts/paper_experiments/generate_template_count_registries.py \
#               --task_root $DATA_ROOT/csibench/multitask/har
#
# Usage:
#   bash scripts/paper_experiments/run_template_count_ablation.sh              # train + eval all
#   DRY_RUN=1 bash scripts/paper_experiments/run_template_count_ablation.sh    # print commands
#   N_TPL="1 3" bash scripts/paper_experiments/run_template_count_ablation.sh  # subset of variants

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="${REPO_ROOT:-$(cd "${SCRIPT_DIR}/../.." && pwd)}"
DATA_ROOT="${DATA_ROOT:-${REPO_ROOT}/data/Dataset}"
MODEL_ROOT="${MODEL_ROOT:-${REPO_ROOT}/runs}"
CONFIG="${CONFIG:-${REPO_ROOT}/configs/experiment/default.yaml}"

ENCODER="resnet18_1d"
TEXT_ENCODER="clip_vit_b32"
DRY_RUN="${DRY_RUN:-0}"

TASK_ROOT="${DATA_ROOT}/csibench/multitask/har"
REGISTRY_BASE="${REPO_ROOT}/data/generated_texts/ablation_template_count"

N_TPL="${N_TPL:-1 3 5 10}"
METHODS="${METHODS:-clip_infonce siglip}"

export PYTHONPATH="${REPO_ROOT}:${PYTHONPATH:-}"

log() { echo -e "\n\033[1;34m[$(date '+%H:%M:%S')] $*\033[0m"; }

run_cmd() {
    if [[ "$DRY_RUN" == "1" ]]; then
        echo "[DRY RUN] $*"
        return 0
    fi
    "$@"
}

# ------------------------------------------------------------------
# Pre-flight checks
# ------------------------------------------------------------------
preflight() {
    local missing=0
    for n in $N_TPL; do
        local reg="${REGISTRY_BASE}/${n}tpl/pair_registry.json"
        if [[ ! -f "$reg" ]] && [[ "$DRY_RUN" != "1" ]]; then
            echo "ERROR: Registry not found: ${reg}"
            missing=1
        fi
    done
    if [[ "$missing" == "1" ]]; then
        echo ""
        echo "Generate registries first:"
        echo "  python scripts/paper_experiments/generate_template_count_registries.py \\"
        echo "      --task_root ${TASK_ROOT}"
        exit 1
    fi
}

# ------------------------------------------------------------------
# Generate text embeddings for each registry variant
# ------------------------------------------------------------------
generate_embeddings() {
    log "=== Generating text embeddings for each registry variant ==="
    for n in $N_TPL; do
        local reg_path="${REGISTRY_BASE}/${n}tpl/pair_registry.json"
        local emb_path="${REGISTRY_BASE}/${n}tpl/text_embeddings_${TEXT_ENCODER}.h5"
        if [[ -f "$emb_path" ]] && [[ "$DRY_RUN" != "1" ]]; then
            log "Embeddings already exist: ${emb_path} — skipping"
            continue
        fi
        log "Generating embeddings for ${n}tpl variant..."
        run_cmd python scripts/generate_text_embeddings.py \
            --registry_path "$reg_path" \
            --output_path "$emb_path" \
            --encoder "${TEXT_ENCODER}"
    done
}

# ------------------------------------------------------------------
# Train + evaluate one variant
# ------------------------------------------------------------------
train_and_eval() {
    local n_tpl="$1"
    local method="$2"

    local reg_path="${REGISTRY_BASE}/${n_tpl}tpl/pair_registry.json"
    local emb_path="${REGISTRY_BASE}/${n_tpl}tpl/text_embeddings_${TEXT_ENCODER}.h5"
    local ckpt_dir="${MODEL_ROOT}/checkpoints/ablation_template_count_rerun/${method}_${n_tpl}tpl"
    local ckpt_path="${ckpt_dir}/csibench-har-${method}/best.pt"
    local results_dir="${MODEL_ROOT}/results/ablations/template_count_rerun/${method}_${n_tpl}tpl"

    log "=== Training: ${method} / ${n_tpl} templates ==="
    log "  registry:       ${reg_path}"
    log "  embeddings:     ${emb_path}"
    log "  checkpoint_dir: ${ckpt_dir}"
    log "  results_dir:    ${results_dir}"

    run_cmd python -m training.train \
        --config "$CONFIG" \
        --override \
            dataset=csibench \
            task=har \
            "method=${method}" \
            "csi_encoder.name=${ENCODER}" \
            "task_root=${TASK_ROOT}" \
            "registry_path=${reg_path}" \
            "text_embeddings_path=${emb_path}" \
            "logging.checkpoint_dir=${ckpt_dir}" \
            "text_generation.text_level=level1" \
            "text_generation.num_paraphrases=${n_tpl}"

    if [[ "$DRY_RUN" == "1" ]] || [[ -f "$ckpt_path" ]]; then
        log "=== Evaluating: ${method} / ${n_tpl} templates ==="
        run_cmd python -m scripts.run_evaluate \
            --checkpoint "$ckpt_path" \
            --config "$CONFIG" \
            --override \
                dataset=csibench \
                task=har \
                "method=${method}" \
                "csi_encoder.name=${ENCODER}" \
                "task_root=${TASK_ROOT}" \
                "registry_path=${reg_path}" \
                "text_embeddings_path=${emb_path}" \
            --eval_protocols zero_shot cross_task visualization \
            --data_root "$DATA_ROOT" \
            --output_dir "$results_dir" \
            --no_timestamp

        log "Results for ${method} / ${n_tpl}tpl:"
        if [[ -f "${results_dir}/metrics.json" ]]; then
            python3 -c "
import json
with open('${results_dir}/metrics.json') as f:
    m = json.load(f)
zs = m.get('zero_shot', {})
print(f'  Zero-shot accuracy:    {zs.get(\"accuracy\", \"N/A\")}')
print(f'  Zero-shot weighted F1: {zs.get(\"weighted_f1\", \"N/A\")}')
lp = m.get('visualization', {}).get('linear_probe', {})
if lp:
    print(f'  Linear probe accuracy: {lp.get(\"accuracy\", \"N/A\")}')
"
        fi
    else
        log "WARNING: Checkpoint not found at ${ckpt_path} — skipping eval"
    fi
}

# ------------------------------------------------------------------
# Summary table
# ------------------------------------------------------------------
generate_summary() {
    log "=== Template Count Ablation Summary ==="
    python3 -c "
import json
from pathlib import Path

results_root = Path('${MODEL_ROOT}/results/ablations/template_count_rerun')

print()
print('## Table 4d (rerun) — Template Count Ablation (HAR, Level-1 only)')
print('| Method | Templates/class | Zero-Shot Acc | Weighted F1 | Linear Probe |')
print('|--------|-----------------|---------------|-------------|--------------|')
for method in ['clip_infonce', 'siglip']:
    for n in [1, 3, 5, 10]:
        mf = results_root / f'{method}_{n}tpl' / 'metrics.json'
        if mf.exists():
            m = json.load(open(mf))
            zs = m.get('zero_shot', {})
            lp = m.get('visualization', {}).get('linear_probe', {})
            acc = f'{zs[\"accuracy\"]:.1%}' if isinstance(zs.get('accuracy'), float) else 'N/A'
            f1 = f'{zs[\"weighted_f1\"]:.1%}' if isinstance(zs.get('weighted_f1'), float) else 'N/A'
            lpa = f'{lp[\"accuracy\"]:.1%}' if isinstance(lp.get('accuracy'), float) else 'N/A'
            print(f'| {method} | {n} | {acc} | {f1} | {lpa} |')
        else:
            print(f'| {method} | {n} | -- | -- | -- |')
print()
"
}

# ------------------------------------------------------------------
# Main
# ------------------------------------------------------------------
preflight
generate_embeddings

for n in $N_TPL; do
    for method in $METHODS; do
        train_and_eval "$n" "$method"
    done
done

generate_summary

log "=== Template count ablation complete ==="
